const grid = document.getElementById("productGrid");
const $ = id => document.getElementById(id);
function saveState(){localStorage.setItem("slp_cart",JSON.stringify(cart));localStorage.setItem("slp_favorites",JSON.stringify(favorites));}
function filteredProducts(){
 let arr=PRODUCTS.filter(p=>(selectedCategory==="Todas"||p.category===selectedCategory)&&
 (p.name.toLowerCase().includes(searchTerm)||p.category.toLowerCase().includes(searchTerm)||p.sku.toLowerCase().includes(searchTerm)));
 if(sortMode==="price-low")arr.sort((a,b)=>a.price-b.price);
 if(sortMode==="price-high")arr.sort((a,b)=>b.price-a.price);
 if(sortMode==="name")arr.sort((a,b)=>a.name.localeCompare(b.name,"es"));
 if(sortMode==="featured")arr.sort((a,b)=>(b.tag==="Destacado")-(a.tag==="Destacado"));
 return arr;
}
function renderProducts(){
 const arr=filteredProducts(), start=(currentPage-1)*PAGE_SIZE, visible=arr.slice(start,start+PAGE_SIZE);
 $("resultCount").textContent=`Mostrando ${arr.length?start+1:0}–${Math.min(start+PAGE_SIZE,arr.length)} de ${arr.length} productos`;
 grid.innerHTML=visible.length?visible.map(p=>`<article class="product-card">
  <div class="product-image"><img src="${p.image}" alt="${p.name}" loading="lazy">${p.tag?`<span class="sale-tag">${p.tag}</span>`:""}
  <button class="favorite-btn ${favorites.includes(p.id)?"is-favorite":""}" data-fav="${p.id}" aria-label="Guardar favorito">♡</button>
  <button class="quick-view" data-view="${p.id}">Vista rápida</button></div>
  <div class="product-info"><p class="product-category">${p.category}</p><h3>${p.name}</h3><div class="product-meta">${p.sku} · Disponibilidad por confirmar</div>
  <div class="product-bottom"><strong class="price">${money(p.price)}</strong><button class="add-button" data-add="${p.id}">＋ Agregar</button></div></div></article>`).join(""):`<div class="no-results"><h3>No encontramos productos</h3><p>Prueba con otra palabra o cambia los filtros.</p><button class="btn btn-yellow" id="clearFilters">Limpiar filtros</button></div>`;
 const pages=Math.ceil(arr.length/PAGE_SIZE);
 $("pagination").innerHTML=Array.from({length:pages},(_,i)=>`<button class="page-btn ${currentPage===i+1?"active":""}" data-page="${i+1}">${i+1}</button>`).join("");
 $("categorySelect").value=selectedCategory;
}
function updateCart(){
 const count=cart.reduce((s,x)=>s+x.qty,0), total=cart.reduce((s,x)=>s+PRODUCTS.find(p=>p.id===x.id).price*x.qty,0);
 $("cartCount").textContent=count;$("cartTotal").textContent=money(total);
 $("cartItems").innerHTML=cart.length?cart.map(x=>{const p=PRODUCTS.find(v=>v.id===x.id);return `<div class="cart-item"><img src="${p.image}" alt="${p.name}"><div><h4>${p.name}</h4><small>${money(p.price)}</small><div class="quantity"><button data-minus="${p.id}">−</button><b>${x.qty}</b><button data-plus="${p.id}">+</button></div></div><button class="remove-item" data-remove="${p.id}">✕</button></div>`}).join(""):`<div class="empty-cart">Tu carrito está esperando su primer producto. 🚘</div>`;
 saveState();
}
function addCart(id){const item=cart.find(x=>x.id===id);item?item.qty++:cart.push({id,qty:1});updateCart();toast("Producto agregado al carrito");}
function toast(msg){const t=$("toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2100);}
function openCart(){ $("cartDrawer").classList.add("open");$("cartOverlay").classList.add("show");}
function closeCart(){ $("cartDrawer").classList.remove("open");$("cartOverlay").classList.remove("show");}
function contactWhatsApp(message){
 if(WHATSAPP_NUMBER==="573000000000"){toast("Configura el WhatsApp real en store.js");return;}
 window.open("https://wa.me/"+WHATSAPP_NUMBER+"?text="+encodeURIComponent(message),"_blank","noopener");
}
function checkout(){
 if(!cart.length){toast("Tu carrito está vacío");return;}
 const lines=cart.map(x=>{const p=PRODUCTS.find(v=>v.id===x.id);return `• ${p.name} (${p.sku}) x${x.qty} - ${money(p.price*x.qty)}`;});
 const total=cart.reduce((s,x)=>s+PRODUCTS.find(p=>p.id===x.id).price*x.qty,0);
 contactWhatsApp("Hola, Servilujos La Primera. Quiero cotizar este pedido:\n\n"+lines.join("\n")+"\n\nTotal estimado: "+money(total)+"\n\nPor favor confirmen disponibilidad, compatibilidad y entrega.");
}
function showQuickView(id){
 const p=PRODUCTS.find(x=>x.id===id);$("modalContent").innerHTML=`<div class="quick-modal-inner"><img src="${p.image}" alt="${p.name}"><div><p class="product-category">${p.category}</p><h2>${p.name}</h2><p class="sku">${p.sku}</p><strong class="price">${money(p.price)}</strong><p>${p.description}</p><p class="stock-label">● ${p.stock}</p><button class="btn btn-yellow" data-modal-add="${p.id}">Agregar al carrito</button></div></div>`;
 $("productModal").classList.add("show");
}
grid.addEventListener("click",e=>{
 const add=e.target.closest("[data-add]"),view=e.target.closest("[data-view]"),fav=e.target.closest("[data-fav]");
 if(add)addCart(+add.dataset.add);
 if(view)showQuickView(+view.dataset.view);
 if(fav){const id=+fav.dataset.fav;favorites.includes(id)?favorites=favorites.filter(x=>x!==id):favorites.push(id);saveState();renderProducts();}
});
$("modalContent").addEventListener("click",e=>{const b=e.target.closest("[data-modal-add]");if(b){addCart(+b.dataset.modalAdd);$("productModal").classList.remove("show");}});
$("productModal").addEventListener("click",e=>{if(e.target.id==="productModal")e.currentTarget.classList.remove("show");});
$("closeModal").addEventListener("click",()=>$("productModal").classList.remove("show"));
$("searchInput").addEventListener("input",e=>{searchTerm=e.target.value.toLowerCase().trim();currentPage=1;renderProducts();});
$("categorySelect").addEventListener("change",e=>{selectedCategory=e.target.value;currentPage=1;renderProducts();});
$("sortSelect").addEventListener("change",e=>{sortMode=e.target.value;renderProducts();});
$("pagination").addEventListener("click",e=>{const b=e.target.closest("[data-page]");if(b){currentPage=+b.dataset.page;renderProducts();window.scrollTo({top:$("catalogTop").offsetTop-100,behavior:"smooth"});}});
$("productGrid").addEventListener("click",e=>{if(e.target.id==="clearFilters"){selectedCategory="Todas";searchTerm="";$("searchInput").value="";currentPage=1;renderProducts();}});
$("cartItems").addEventListener("click",e=>{
 const plus=e.target.closest("[data-plus]"),minus=e.target.closest("[data-minus]"),remove=e.target.closest("[data-remove]");
 if(plus)cart.find(x=>x.id===+plus.dataset.plus).qty++;
 if(minus){const x=cart.find(x=>x.id===+minus.dataset.minus);x.qty--;if(x.qty<1)cart=cart.filter(y=>y!==x);}
 if(remove)cart=cart.filter(x=>x.id!==+remove.dataset.remove);updateCart();
});
$("openCart").addEventListener("click",openCart);$("closeCart").addEventListener("click",closeCart);$("cartOverlay").addEventListener("click",closeCart);
$("checkoutButton").addEventListener("click",checkout);
$("whatsappCatalog").addEventListener("click",()=>contactWhatsApp("Hola, quiero asesoría sobre el catálogo de Servilujos La Primera."));
$("clearAll").addEventListener("click",()=>{selectedCategory="Todas";searchTerm="";sortMode="featured";currentPage=1;$("searchInput").value="";$("sortSelect").value="featured";renderProducts();});
$("productTotal").textContent=PRODUCTS.length;
renderProducts();updateCart();
